module TopModule (
    input clk,
    input [7:0] d,
    output [7:0] q
);

    // Declare 8 D flip-flops
    reg [7:0] d_reg [0:7];

    // D flip-flop always block
    always @(posedge clk) begin
        for (int i = 0; i < 8; i = i + 1) begin
            d_reg[i] <= d[i];
        end
    end

    // Output the current state of the D flip-flops
    assign q = d_reg;

endmodule
